import{z as o,x as s,o as l,c as d,q as t,j as E,D as e,d as n,s as B,S as i}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"可转债与信用混合","description":"","frontmatter":{"title":"可转债与信用混合","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/convertible-credit.md","filePath":"quant/convertible-credit.md","lastUpdated":1791063341000}'),A={name:"quant/convertible-credit.md"};function m(p,a,h,D,c,S){const r=s("Mermaid");return l(),d("div",null,[a[2]||(a[2]=t('<h1 id="可转债与信用混合" tabindex="-1">可转债与信用混合 <a class="header-anchor" href="#可转债与信用混合" aria-label="Permalink to &quot;可转债与信用混合&quot;">​</a></h1><div class="epigraph"><p>可转债同时是股权看涨、发行人赎回权、持有人回售与违约时的回收；信用与股票不能分成两次贴现，否则会把股权部分当成无违约的现金。</p><footer>—— Ingersoll；Brennan &amp; Schwartz；Tsiveriotis &amp; Fernandes；Ayache, Forsyth &amp; Vetzal</footer></div><p>可转债（convertible bond）把公司债的信用暴露和转股期权写在同一张契约上。Ingersoll（1977）、Brennan 与 Schwartz（1977, 1980）用或有权益把转股、赎回当成最优停时，状态是公司价值或股票。1990 年代之后，实务转向可观测的股价加强度违约：Tsiveriotis 与 Fernandes（1998）把价值拆成现金部分与股权部分，现金用含信用的折现、股权用无风险折现。Ayache、Forsyth 与 Vetzal（2003）指出这种拆法在违约时对股权的处理不一致，主张在违约强度框架里对整个 PDE 做跳跃条件。本篇写混合的对象：最优停时、强度、回收与稀释，以及为什么利率常用一因子 <a href="/quant/hull-white">Hull-White</a> 而不是全 <a href="/quant/lmm">LMM</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>契约条款通常包括：持有人把债转成 \\(n\\) 股的权利、发行人在赎回价召回（往往逼迫转股）、持有人在回售日把债卖回、以及发行人违约时债的回收。股票涨，转股价值涨，信用利差往往同时收窄；股票崩，转股权变得不值钱，违约强度上升，债底下跌。若把转债当成「无信用的美式看涨加上一个按信用利差折现的债底」，会在正是两者相关最强的区域——困境——算错。</p><p>要联合建模的是：股价 \\(S\\)（或公司价值 \\(V\\)）、违约强度 \\(\\lambda\\) 或信用利差、利率、以及条款触发的最优停时。维度很容易超过三，树与 PDE 开始吃力。问题不是再写一个 Black–Scholes，而是规定违约时发生什么：股票是否跳到零、转债回收是面值的一个分数还是股价的函数、股权部分是否还在。TF 与 AFV 的分歧就在这条跳跃条件，不是在有没有强度。</p><h3 id="结构模型与强度模型" tabindex="-1">结构模型与强度模型 <a class="header-anchor" href="#结构模型与强度模型" aria-label="Permalink to &quot;结构模型与强度模型&quot;">​</a></h3><p>结构模型（Merton / Ingersoll）里违约是公司价值碰到债的边界，转股是把债换成股权的稀释。优点是股票与信用来自同一 \\(V\\)，相关是内生的；缺点是短端利差难以校准到市场 CDS，边界附近的数值敏感。强度模型把 \\(\\lambda_t\\) 写成 \\(S\\) 的减函数（股价越低越容易违约），CDS 可校准，股票过程外生，违约时对 \\(S\\) 施加跳跃。可转债台现在以后者为主，因为对冲工具是股票、CDS 与利率，而不是不可交易的 \\(V\\)。结构模型仍适合讲稀释与资本结构，不适合逐日 mark。</p><p><span class="marginnote">术语翻译：强度模型是给违约装一个「随时会响的闹钟」，响的概率随股价下跌调高；结构模型则要先估出看不见的公司总价值 \\(V\\)，再判断它何时跌破债务墙。交易台选前者，是因为闹钟可以直接用 CDS 校准，而 \\(V\\) 没有报价。</span></p><p><span class="marginnote">「债底」不是无转股条款的公司债市价。赎回、回售与转股改变发行人与持有人的最优行为，即使深度虚值，条款仍可能在利率或信用移动时变成实值。用一张普通信用债去减得到期权价值，会把条款凸性算进「期权」里。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>强度框架的最小状态是 \\((S,r)\\)，违约强度 \\(\\lambda=\\lambda(S)\\) 或再加一个随机信用因子。未违约时，转债价值 \\(U\\) 满足带提前行权的 PDE / 变分不等式：持有区等于生成元等于 \\(r+\\lambda\\)（或拆成无风险贴现加补偿），转股时 \\(U=nS\\)，赎回时 \\(U=\\max(nS,C_{\\mathrm{call}})\\) 等，具体不等式随条款。违约时 AFV 类型的条件是 \\(U\\) 跳到 \\(\\max(nS,R\\cdot\\mathrm{par})\\) 或 \\(R\\) 乘前一时刻面值，并允许 \\(S\\) 跳到零；若违约后股票仍交易，回收与股票残值要同时规定。</p><p><span class="marginnote">数字实例：无风险利率 2%、一年违约概率 4% 对应 \\(\\lambda\\approx 4\\%\\)，现金部分按约 6% 折现——同样 100 元面值一年后到期，债底只剩约 \\(100/1.06\\approx 94.3\\) 元，而不是按无风险折成的约 98 元。信用一紧，这 3.7 元的差额就是债底的缺口。</span></p><p>Tsiveriotis–Fernandes 把 \\(U=E+B\\)，\\(E\\) 为股权部分（无风险折现）、\\(B\\) 为现金部分（信用折现）。实现简单，能接到现成的信用曲线，但对违约时 \\(E\\) 的处理相当于假设股权部分不受信用事件冲击，会高估困境区的转股价值。Ayache–Forsyth–Vetzal 在同一网格上用强度跳跃替代这种拆分，校准仍可用 CDS 定 \\(\\lambda(S)\\) 的水平，用股票波动定扩散，用历史或权证定跳跃。利率可用确定性曲线，或一因子 Hull–White；随机利率主要影响债底凸性与赎回决策，对高 delta 的转债往往是二阶。</p><h3 id="稀释、强制赎回与回售" tabindex="-1">稀释、强制赎回与回售 <a class="header-anchor" href="#稀释、强制赎回与回售" aria-label="Permalink to &quot;稀释、强制赎回与回售&quot;">​</a></h3><p>转股增加股本，\\(n\\) 本身可能随反稀释条款调整。赎回公告给出一个通知期，持有人在期内仍可转股，这是「强制转股」的机制：赎回价低于转股价值时，理性持有人转股。模型必须包含通知期，否则会低估发行人的期权、高估持有人的凸性。<span class="marginnote">常见误区：初学者容易以为强赎公告是利空、该立刻抛售。实际上赎回价低于转股价值时，强赎只是逼你在通知期内转股或被低价赎走；理性的动作是转股或卖出。在模型里这对应「有效到期被缩短」，凸性随之消失。</span></p><p>回售给持有人一个信用保护：股价低、信用差时，回售把价值抬到回售价附近，除非发行人已经违约。数值上这些是离散行权日上的 \\(\\max\\) 与 \\(\\min\\) 条件，与美式股票期权的连续行权不同，时间网格要对齐条款日历，而不是只对齐到到期。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信用–股权相关的机制是：\\(\\lambda(S)\\) 下降的凸性让股价下跌时折现率上升，债底加速掉，转债的有效凸性比无信用的权证更大，这是「困境凸性」（distress convexity）的来源。对冲上，股票 delta 在平值附近像看涨，在深度虚值区会因信用而重新变大（价值对 \\(S\\) 通过 \\(\\lambda\\) 再进入），出现 delta 的二次上升。若模型把信用冻结，这种二次 delta 不会出现，对冲会在下跌市里不够买。CDS 对冲吸收 \\(\\lambda\\) 的平行移动，吸收不了 \\(\\lambda(S)\\) 形状的错误。</p><p><span class="marginnote">直觉类比：把 \\(\\lambda(S)\\) 想成随车速上升的刹车灵敏度——股价跌得越急，「违约」这脚刹车越容易被踩下，折现率与债底同时恶化。只盯着股价波动的模型，等于装了一辆没有刹车的模拟器。</span></p><p>股价下跌时困境凸性与二次 delta 如何接力：</p>',21)),(l(),E(i,null,{default:e(()=>[B(r,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E8%82%A1%E4%BB%B7%20S%20%E4%B8%8B%E8%B7%8C%22%5D%20--%3E%20B%5B%22%E5%BC%BA%E5%BA%A6%20%CE%BB(S)%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%8A%98%E7%8E%B0%E7%8E%87%20r%2B%CE%BB%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%80%BA%E5%BA%95%E5%8A%A0%E9%80%9F%E4%B8%8B%E8%B7%8C%22%5D%0A%20%20A%20--%3E%20E%5B%22%E8%BD%AC%E8%82%A1%E6%9C%9F%E6%9D%83%E6%9B%B4%E8%99%9A%E5%80%BC%22%5D%0A%20%20D%20--%3E%20F%5B%22%E5%9B%B0%E5%A2%83%E5%87%B8%E6%80%A7%22%5D%0A%20%20E%20--%3E%20F%0A%20%20B%20--%3E%20G%5B%22delta%20%E7%BB%8F%20%CE%BB%20%E9%80%9A%E9%81%93%E4%BA%8C%E6%AC%A1%E4%B8%8A%E5%8D%87%22%5D%0A%20%20F%20--%3E%20H%5B%22%E5%86%BB%E7%BB%93%E4%BF%A1%E7%94%A8%E7%9A%84%E6%A8%A1%E5%9E%8B%E5%AF%B9%E5%86%B2%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20G%20--%3E%20H%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>发行人赎回发生在转股价值明显高于赎回价、且信用允许发行人仍能再融资的区域。信用差时发行人可能无法赎回，持有人的期权多活一段时间——这是信用对赎回权的非对称。模型若允许在任意 \\(S\\) 上按条款赎回，会高估发行人的权利。有的实现用「赎回被信用门控」的启发式，这已离开经典 PDE，但方向与契约现实一致。</p><p><span class="marginnote">波动率校准常拿权证或隐含波动，但权证没有同一套信用。用无信用的股票期权波动直接当转债扩散，会在困境区重复计算信用：一次在 \\(\\lambda\\)，一次在膨胀的 \\(\\sigma\\)。应把股票期权当成无违约或轻违约名下的 \\(\\sigma\\)，把尾部留给 \\(\\lambda\\) 与跳跃。</span></p><h3 id="利率与信用的期限结构" tabindex="-1">利率与信用的期限结构 <a class="header-anchor" href="#利率与信用的期限结构" aria-label="Permalink to &quot;利率与信用的期限结构&quot;">​</a></h3><p>债底对利率久期仍在，尤其是高票息、远赎回、低 delta 的「债性」转债。用扁平信用利差加扁平利率会把关键利率风险集中到一个桶。更好的做法是：贴现用无风险 / OIS 曲线，强度用 CDS 期限结构，\\(\\lambda\\) 再乘一个 \\(S\\) 的函数做杠杆。不要把整条信用曲线压成一个常数 \\(z\\)-spread 再塞进 Black–Scholes，除非组合真的只剩短到期、高 delta 的股权型转债。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用 TF 拆分给深度困境的转债标价还声称已处理信用。不要忽略通知期与交易日惯例。不要在 PDE 里用股票本地波动拟合全部微笑，又用很陡的 \\(\\lambda(S)\\) 拟合全部 CDS，两者在尾部抢同一套下跌路径。离散分红、稀释、强制转股限制（make-whole）都是一等条款，不是「加几个基点」。</p><p>数值上，强度在 \\(S\\to 0\\) 时若爆炸，显式格式会不稳定，应对 \\(\\lambda\\) 封顶或用隐式。Monte Carlo 加最优赎回 / 转股需要回归，与 Bermudan 利率产品同一类误差。中国市场的转债还有下修、强赎、回售与正股停牌，模型必须把监管条款写成离散事件，不能只用 Ingersoll 的连续公司价值故事。利率侧保持低维，是为了给信用与股权留计算预算。</p><p><span class="marginnote">回收率 \\(R\\) 与强度 \\(\\lambda\\) 在价格上接近不可分：高 \\(\\lambda\\) 配高 \\(R\\) 可以假装成低 \\(\\lambda\\) 配低 \\(R\\)。应用 CDS 与回收惯例固定其中一个，再估另一个，并在压力里单独扫 \\(R\\)，不要让优化器同时动两者。</span></p>',8)),(l(),E(i,null,{default:e(()=>[B(r,{id:"mermaid-86",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E8%82%A1%E4%BB%B7%20S%22%5D%20--%3E%20HOLD%5B%22%E6%8C%81%E6%9C%89%E5%8C%BA%20PDE%22%5D%0A%20%20LAM%5B%22%E5%BC%BA%E5%BA%A6%20%CE%BB(S)%20%2F%20CDS%22%5D%20--%3E%20HOLD%0A%20%20R%5B%22%E5%88%A9%E7%8E%87%E6%9B%B2%E7%BA%BF%20%2F%20HW%22%5D%20--%3E%20HOLD%0A%20%20HOLD%20--%3E%20CV%5B%22%E8%BD%AC%E8%82%A1%3A%20nS%22%5D%0A%20%20HOLD%20--%3E%20CALL%5B%22%E8%B5%8E%E5%9B%9E%3A%20%E9%80%9A%E7%9F%A5%E6%9C%9F%20%2B%20%E5%BC%BA%E5%88%B6%E8%BD%AC%E8%82%A1%22%5D%0A%20%20HOLD%20--%3E%20PUT%5B%22%E5%9B%9E%E5%94%AE%22%5D%0A%20%20HOLD%20--%3E%20DEF%5B%22%E8%BF%9D%E7%BA%A6%E8%B7%B3%E8%B7%83%3A%20%E5%9B%9E%E6%94%B6%20R%22%5D%0A%20%20TF%5B%22TF%3A%20%E7%8E%B0%E9%87%91%20%2F%20%E8%82%A1%E6%9D%83%E5%88%86%E6%8A%98%E7%8E%B0%22%5D%20-.-%3E%7C%22%E5%9B%B0%E5%A2%83%E5%8C%BA%E4%B8%8D%E4%B8%80%E8%87%B4%22%7C%20AFV%5B%22AFV%3A%20%E7%BB%9F%E4%B8%80%E5%BC%BA%E5%BA%A6%E8%B7%B3%E8%B7%83%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可转债是股权期权、赎回、回售与违约回收的混合最优停时问题，信用与股票必须同一定价核。</li><li>Ingersoll、Brennan–Schwartz 给出结构 / 或有权益传统；实务以股价加强度为主。</li><li>Tsiveriotis–Fernandes 拆分实现方便，但违约时对股权部分的处理与强度框架不一致；Ayache–Forsyth–Vetzal 用跳跃条件修正。</li><li>困境区会出现因 \\(\\lambda(S)\\) 而来的二次 delta；冻结信用会低估下跌对冲。</li><li>利率保持低维（曲线加可选 Hull–White），计算预算留给条款日历、稀释与信用跳跃。</li><li>出处：Ingersoll, <em>JFE</em>, 1977；Brennan &amp; Schwartz, <em>Journal of Finance</em>, 1977 与 <em>JFQA</em>, 1980；Tsiveriotis &amp; Fernandes, <em>Journal of Fixed Income</em>, 1998；Ayache, Forsyth &amp; Vetzal, <em>Journal of Derivatives</em>, 2003；强度贴现见 Duffie &amp; Singleton, <em>RFS</em>, 1999。</li></ul>',2))])}const u=o(A,[["render",m]]);export{b as __pageData,u as default};
